#include <signal.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>

int pipefd[2];

void sigint(int s){
  char c = 1;
  write(pipefd[1], &c, 1);
}

int main(){
  pipe(pipefd);
  struct sigaction sa;
  sa.sa_handler = sigint;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = 0;
  sigaction(SIGINT, &sa, NULL);

  char buf;
  while (read(pipefd[0], &buf, 1) > 0) {
    // termination requested
  }
  return 0;
}
```

